"""Refresh guide coordinates and verify source introductions; preserve image metadata.

Run explicitly with internet: python tests/enrich_guides.py
Guide copy is editorial, based on the linked geographic/landmark introductions.
"""
import json
import urllib.parse
from pathlib import Path
from verify_sources import request_json

ROOT = Path(__file__).resolve().parents[1]
# Title, overview, highlights, activities, cultural context, practical planning tip.
GUIDES = [
    ('Dolomites', 'In northeastern Italy, the Dolomites form a dramatic part of the Alps. Pale rock towers, wooded slopes and high mountain valleys give this region its distinctive skyline. The photograph looks toward the mountains around Cortina d’Ampezzo.', ['Limestone peaks', 'Alpine valleys', 'Mountain panoramas'], ['Landscape photography', 'Walking', 'Mountain scenery'], 'Mountain settlements connect the landscape with the everyday life of the Italian Alps.', 'Choose a route suited to your experience and check current local trail and weather information.'),
    ('Kinkaku-ji', 'Kinkaku-ji is a Zen Buddhist temple in Kyoto, known for its golden pavilion beside a reflective pond. The garden setting combines carefully composed views, water and architecture. It offers a quieter perspective on a city celebrated for historic religious sites.', ['Golden pavilion', 'Reflecting pond', 'Temple gardens'], ['Garden walks', 'Architecture', 'Cultural discovery'], 'This is a religious setting as well as an architectural landmark; observe posted guidance and give worshippers space.', 'Check the temple’s current visitor information and photography guidance before planning a visit.'),
    ('Oia, Greece', 'Oia is a settlement on Santorini, a Greek island in the Aegean Sea. Its buildings follow the slopes above the volcanic caldera, with terraces and narrow paths creating layered views of the water. The photograph captures its coastal architecture in warm light.', ['Caldera views', 'Coastal architecture', 'Village lanes'], ['Coastal walks', 'Architecture', 'Landscape photography'], 'The village’s built form reflects life on a steep volcanic island.', 'Plan a walking route at your own pace; consult local guidance for accessible paths and transport.'),
    ('Fitz Roy', 'Fitz Roy is a granite mountain in the southern Patagonian Andes, on the Argentina–Chile border. Its sharp profile and surrounding lakes make the landscape particularly striking. This gallery places the viewpoint in Argentina, rather than treating Patagonia as a single country.', ['Granite skyline', 'Laguna Capri scenery', 'Patagonian landscapes'], ['Landscape photography', 'Walking', 'Mountain scenery'], 'Patagonia is a cross-border region; this guide focuses on the Fitz Roy landscape.', 'Check current park guidance, route conditions and weather rather than relying on a photograph to judge a walk.'),
    ('Pura Ulun Danu Bratan', 'Pura Ulun Danu Bratan is a Hindu temple complex beside Lake Bratan in Bali, Indonesia. Water, mountain surroundings and layered temple roofs define its lakeside setting. The place connects a striking landscape with Bali’s living religious traditions.', ['Lakeside temple', 'Lake Bratan', 'Layered temple roofs'], ['Cultural discovery', 'Architecture', 'Landscape photography'], 'The temple is an active sacred place; follow local dress and visitor guidance.', 'Consult current visitor information and respect any areas reserved for religious use.'),
    ('Manhattan', 'Manhattan is one of New York City’s five boroughs and contains many of its best-known skyscrapers and public spaces. Its dense street grid and skyline offer a very different kind of landscape from the gallery’s remote destinations. The photograph looks across Midtown’s architecture.', ['Midtown skyline', 'Skyscraper architecture', 'Urban streetscapes'], ['City walks', 'Architecture', 'Urban photography'], 'Manhattan is a lived-in urban district, with residential, cultural and commercial spaces sharing the same streets.', 'Choose a compact walking area and consult current transit and attraction information for your itinerary.'),
    ('Cappadocia', 'Cappadocia is a historic region in central Türkiye, associated with unusual volcanic rock formations and rock-cut buildings. Erosion has shaped the landscape into towers, ridges and valleys. Its architecture and geology are closely intertwined.', ['Rock formations', 'Valley landscapes', 'Rock-cut architecture'], ['Landscape photography', 'Walking', 'Cultural discovery'], 'Historic rock-cut spaces form part of a wider inhabited cultural landscape.', 'Check current access arrangements for specific valleys and sites; select walking routes with local guidance.'),
    ('Jemaa el-Fnaa', 'Jemaa el-Fnaa is a major square and gathering place in Marrakech’s medina. Its public life brings together trade, performance and everyday movement. The square provides a starting point for understanding the social character of the historic city.', ['Medina square', 'Public gathering space', 'Historic urban setting'], ['Cultural discovery', 'City walks', 'Urban photography'], 'The square is a working public space. Ask permission before taking close photographs of people or performers.', 'Plan your route through the medina and check local visitor guidance; agree any paid service in advance.'),
    ('Moraine Lake', 'Moraine Lake lies in Banff National Park in Alberta, Canada. Glacial water and the surrounding Valley of the Ten Peaks create one of the Canadian Rockies’ recognizable mountain compositions. The gallery’s Banff entry focuses on this lake rather than the whole park.', ['Glacial lake', 'Valley of the Ten Peaks', 'Rocky Mountain scenery'], ['Landscape photography', 'Walking', 'Mountain scenery'], 'A national park is a protected landscape; use designated visitor areas and respect wildlife.', 'Check the park’s current access and transport arrangements before going to the lake.'),
    ('Al-Khazneh', 'Al-Khazneh, often called the Treasury, is a monumental rock-cut facade at Petra in Jordan. Petra was a Nabataean city whose remains include buildings and spaces carved into sandstone. The photograph shows one landmark within a much larger archaeological landscape.', ['Rock-cut facade', 'Sandstone landscape', 'Nabataean heritage'], ['Architecture', 'Cultural discovery', 'Walking'], 'The site’s significance extends beyond a single facade to the wider archaeological setting.', 'Check current site information, choose a manageable walking route and respect protected areas.'),
    ('Marina Bay, Singapore', 'Marina Bay is a waterfront area in Singapore associated with contemporary architecture and urban redevelopment. Buildings, water and promenades create changing city views. The gallery focuses on the relationship between the bay and its surrounding skyline.', ['Waterfront skyline', 'Contemporary architecture', 'Bay-side public spaces'], ['City walks', 'Architecture', 'Urban photography'], 'The bay is part of an active city; public walkways are shared by residents, workers and visitors.', 'Plan a short waterfront route and consult current information for any attraction you want to enter.'),
    ('Hawa Mahal', 'Hawa Mahal stands in Jaipur, India, and is known for its many-windowed sandstone facade. The building’s intricate screen-like frontage is closely associated with the city’s architectural identity. It is a focused introduction to Jaipur’s historic built environment.', ['Sandstone facade', 'Window patterns', 'Historic Jaipur setting'], ['Architecture', 'Cultural discovery', 'Urban photography'], 'Look beyond the facade’s pattern to the historic urban setting around it.', 'Check current entry and photography arrangements and be considerate when photographing from busy streets.'),
    ('Geirangerfjord', 'Geirangerfjord is a fjord in western Norway, where steep mountain slopes rise above a narrow inlet. Its scale comes from the relationship between water, valley walls and small settlements. The landscape rewards both broad views and attention to small details.', ['Steep fjord walls', 'Water and mountain views', 'Valley landscapes'], ['Landscape photography', 'Walking', 'Coastal scenery'], 'Small communities share this landscape with visitors; respect homes and working spaces.', 'Check local transport and access information, and choose viewpoints appropriate to conditions.'),
    ('Hạ Long Bay', 'Hạ Long Bay lies in northeastern Vietnam and is known for limestone islands and marine scenery. The islands create layers of rock and water rather than a continuous coastline. The gallery highlights the distinctive karst landscape of the bay.', ['Limestone islands', 'Marine karst scenery', 'Layered bay views'], ['Coastal scenery', 'Landscape photography', 'Geology'], 'The bay is a wider natural and inhabited landscape, rather than a single viewpoint.', 'Consult current local visitor information and choose operators and activities that respect the bay’s environment.'),
    ('Table Mountain', 'Table Mountain is a flat-topped mountain overlooking Cape Town in South Africa. It gives the city a distinctive backdrop and connects urban views with a much larger natural landscape. The mountain’s shape is recognizable from many parts of the city.', ['Flat-topped skyline', 'Mountain and city views', 'Coastal setting'], ['Landscape photography', 'City walks', 'Mountain scenery'], 'The mountain is part of Cape Town’s everyday sense of place as well as a visitor landmark.', 'Consult current local access and weather guidance before choosing a mountain activity.'),
    ('Machu Picchu', 'Machu Picchu is an Inca archaeological site in the Peruvian Andes. Stone buildings and terraces follow the mountain terrain above a deeply cut valley. Its relationship with the surrounding cloud-forest landscape is central to the experience of the site.', ['Inca stonework', 'Mountain terraces', 'Andean landscape'], ['Cultural discovery', 'Architecture', 'Landscape photography'], 'This is a protected archaeological place; keep to designated routes and respect its remains.', 'Use current official visitor information for entry and route planning; arrangements can change.'),
    ('Amalfi Coast', 'The Amalfi Coast is a coastal area of Campania in southern Italy. Settlements, cultivated slopes and roads occupy a narrow landscape between mountains and the Mediterranean. The gallery emphasizes the close relationship between coastal villages and their terrain.', ['Coastal villages', 'Mediterranean views', 'Steep cultivated slopes'], ['Coastal walks', 'Architecture', 'Landscape photography'], 'These are inhabited settlements; consider residents when using narrow streets and viewpoints.', 'Plan travel between villages using current local transport information rather than assuming short map distances mean short journeys.'),
    ('Skógafoss', 'Skógafoss is a waterfall on the Skógá River in southern Iceland. A broad curtain of water falls over a former coastal cliff, with green slopes framing the scene. The gallery’s viewpoint highlights the contrast between moving water and the dark rock face.', ['Broad waterfall', 'River landscape', 'Green cliff setting'], ['Landscape photography', 'Walking', 'Waterfall scenery'], 'Treat the surroundings as a shared natural site and follow marked visitor routes.', 'Check local conditions and stay within designated areas; spray can make nearby surfaces wet.'),
]

if __name__ == '__main__':
    source = ROOT / 'js/data.js'
    photos = json.loads(source.read_text(encoding='utf-8').split('window.ATLAS_PHOTOS = ', 1)[1].rstrip().rstrip(';'))
    response = request_json('https://en.wikipedia.org/w/api.php', action='query', titles='|'.join(g[0] for g in GUIDES), prop='extracts|coordinates', exintro=1, explaintext=1, exchars=900, colimit='max', redirects=1, format='json')
    pages = {page['title']: page for page in response['query']['pages'].values()}
    for redirect in response['query'].get('redirects', []):
        pages[redirect['from']] = pages[redirect['to']]
    lines = ['# Destination guide sources', '', 'Geographic introductions and map-pin coordinates consulted on 29 October 2026 through the Wikipedia API. The guides use original editorial summaries, not copied article text. Pins indicate the named landmark or representative viewpoint, not a route, exact entrance, or the boundary of an entire region. Practical tips are general planning suggestions; check current local information before travel.', '', 'Interactive map: [OpenStreetMap export documentation](https://wiki.openstreetmap.org/wiki/Export) and [© OpenStreetMap contributors / ODbL](https://www.openstreetmap.org/copyright). Map tiles need internet. The map loads only when opened.', '']
    for photo, guide in zip(photos, GUIDES):
        title, overview, highlights, activities, context, tip = guide
        page = pages[title]
        assert len(page.get('extract', '')) > 100, title
        point = page['coordinates'][0]
        url = 'https://en.wikipedia.org/wiki/' + urllib.parse.quote(page['title'].replace(' ', '_'))
        photo['guide'] = dict(overview=overview, highlights=highlights, activities=activities, context=context, tip=tip, latitude=point['lat'], longitude=point['lon'], pinLabel=title, sourceUrl=url)
        lines += [f"- **{photo['destination']}** — [{page['title']}]({url}); representative pin: {point['lat']}, {point['lon']}."]
    source.write_text('// Verified Commons photography and sourced editorial guides. See docs/IMAGE_CREDITS.md and docs/DESTINATION_SOURCES.md.\nwindow.ATLAS_PHOTOS = ' + json.dumps(photos, ensure_ascii=False, indent=2) + ';\n', encoding='utf-8')
    (ROOT / 'docs/DESTINATION_SOURCES.md').write_text('\n'.join(lines) + '\n', encoding='utf-8')
    print('Verified and enriched all 18 destination guides and map coordinates.')
